```groovy
// Jenkinsfile (Declarative Pipeline)
pipeline {
  agent any

  options {
    timestamps()
    ansiColor('xterm')
    disableConcurrentBuilds()
    buildDiscarder(logRotator(numToKeepStr: '30', artifactNumToKeepStr: '10'))
  }

  parameters {
    choice(name: 'BUILD_TOOL', choices: ['auto', 'maven', 'gradle', 'npm', 'make'], description: 'Build tool to run')
    booleanParam(name: 'RUN_TESTS', defaultValue: true, description: 'Run tests stage')
  }

  environment {
    CI = 'true'
  }

  stages {
    stage('Checkout') {
      steps {
        checkout scm
        script {
          env.GIT_COMMIT_SHORT = sh(returnStdout: true, script: 'git rev-parse --short HEAD').trim()
        }
      }
    }

    stage('Prepare') {
      steps {
        sh '''
          set -euo pipefail
          echo "Branch: ${BRANCH_NAME:-unknown}"
          echo "Commit: ${GIT_COMMIT_SHORT:-unknown}"
          echo "Workspace: $WORKSPACE"
        '''
      }
    }

    stage('Build') {
      steps {
        script {
          def tool = params.BUILD_TOOL
          if (tool == 'auto') {
            if (fileExists('pom.xml')) tool = 'maven'
            else if (fileExists('build.gradle') || fileExists('build.gradle.kts')) tool = 'gradle'
            else if (fileExists('package.json')) tool = 'npm'
            else if (fileExists('Makefile')) tool = 'make'
            else error("BUILD_TOOL=auto but no known build files found (pom.xml, build.gradle(.kts), package.json, Makefile).")
          }

          if (tool == 'maven') {
            sh 'mvn -B -ntp clean package'
          } else if (tool == 'gradle') {
            sh './gradlew --no-daemon clean build'
          } else if (tool == 'npm') {
            sh 'npm ci'
            sh 'npm run build'
          } else if (tool == 'make') {
            sh 'make'
          } else {
            error("Unsupported BUILD_TOOL: ${tool}")
          }
        }
      }
    }

    stage('Test') {
      when { expression { return params.RUN_TESTS } }
      steps {
        script {
          def tool = params.BUILD_TOOL
          if (tool == 'auto') {
            if (fileExists('pom.xml')) tool = 'maven'
            else if (fileExists('build.gradle') || fileExists('build.gradle.kts')) tool = 'gradle'
            else if (fileExists('package.json')) tool = 'npm'
            else if (fileExists('Makefile')) tool = 'make'
          }

          if (tool == 'maven') {
            sh 'mvn -B -ntp test'
          } else if (tool == 'gradle') {
            sh './gradlew --no-daemon test'
          } else if (tool == 'npm') {
            sh 'npm test --if-present'
          } else if (tool == 'make') {
            sh 'make test || true'
          } else {
            sh 'echo "No tests configured for tool: ${tool}"'
          }
        }
      }
      post {
        always {
          junit allowEmptyResults: true, testResults: '**/target/surefire-reports/*.xml, **/build/test-results/test/*.xml, **/test-results/**/*.xml'
        }
      }
    }

    stage('Archive') {
      steps {
        archiveArtifacts artifacts: '**/target/*.jar, **/build/libs/*.jar, **/dist/**, **/build/**/reports/**', allowEmptyArchive: true, fingerprint: true
      }
    }
  }

  post {
    success {
      echo "Build succeeded: ${env.JOB_NAME} #${env.BUILD_NUMBER}"
    }
    failure {
      echo "Build failed: ${env.JOB_NAME} #${env.BUILD_NUMBER}"
    }
    always {
      cleanWs(deleteDirs: true, disableDeferredWipeout: true)
    }
  }
}
